export function t(text: string, vars?: Record<string, string | number>): string {
  const lang = currentLanguage();
  let out = !lang || lang === "en" ? text : (packs[lang]?.[text] ?? packs[lang.split("-")[0] ?? ""]?.[text] ?? text);
  if (!vars) return out;
  for (const [key, value] of Object.entries(vars)) out = out.replaceAll(`{${key}}`, latinFill(lang, value));
  return out;
}

function latinFill(lang: string, value: string | number): string {
  if (lang === "la") {
    if (typeof value === "number" && Number.isInteger(value)) return romanNumeral(value);
    if (typeof value === "string" && /^-?\d+$/.test(value)) return romanNumeral(Number(value));
  }
  return String(value);
}

/** Known sentences that carry a name or a number in the middle. */
export function tLine(text: string): string {
  const patterns: [RegExp, string, string][] = [
    [/^(.*) is read and written with your notes\.$/, "{name} is read and written with your notes.", "name"],
    [/^Could not read (.*)\.$/, "Could not read {name}.", "name"],
    [/^Could not write (.*)\.$/, "Could not write {name}.", "name"],
    [/^(.*) is not a TLNotes sync file, so it was left alone\.$/, "{name} is not a TLNotes sync file, so it was left alone.", "name"],
    [/^(.*) needs permission again\. Choose it once more\.$/, "{name} needs permission again. Choose it once more.", "name"],
    [/^Downloading (\d+)%$/, "Downloading {n}%", "n"],
  ];
  for (const [pattern, key, slot] of patterns) {
    const match = text.match(pattern);
    if (match?.[1] != null) return t(key, { [slot]: match[1] });
  }
  return t(text);
}
